<?php
require_once __DIR__.'/includes/bootstrap.php';
$gameId=(int)($_GET['game_id']??0);$teamId=(int)($_GET['team_id']??0);
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ARQWAR · Equipo</title><link href="assets/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/app.css"></head><body class="gm-body"><main class="container py-4"><div class="brand mb-3">ARQWAR <span>TEAM VIEW</span></div><div id="teamView" class="panel p-4">Cargando...</div></main><script>
const gid=<?=$gameId?>,tid=<?=$teamId?>;const e=s=>String(s??'').replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','\"':'&quot;'}[c]));
async function load(){const r=await fetch(`api/state.php?game_id=${gid}&t=${Date.now()}`);const j=await r.json();if(!j.ok)return;const d=j.data,t=d.teams.find(x=>Number(x.team.id)===tid);if(!t){document.getElementById('teamView').innerHTML='Equipo no encontrado';return}const s=t.stats;document.getElementById('teamView').innerHTML=`<div class="d-flex justify-content-between"><div><div class="eyebrow">${e(t.team.name)}</div><div class="score-title">PUNTOS ACUMULADOS</div><h1>${t.score}<small class="text-secondary fs-6">/1000</small></h1></div><div class="text-end"><b>REP ${t.team.reputation}</b><br><b>SLA ${Number(t.team.sla).toFixed(3)}%</b></div></div><div class="row g-2 my-3">${Object.entries(s).map(([k,v])=>`<div class="col-6 col-md-4"><div class="mini-card"><span>${e(k.toUpperCase())}</span><b class="fs-3">${v}</b></div></div>`).join('')}</div><div class="team-members-strip my-3"><div class="eyebrow mb-2">PARTICIPANTES</div><div class="d-flex flex-wrap gap-2">${(t.members||[]).map(m=>`<span class="member-name-pill">${e(m.name)}<small>${e(m.role||'Participante')}</small></span>`).join('')||'<span class="text-secondary">Sin participantes registrados</span>'}</div></div><div class="dice-rule-note my-3">🎲 Dado: ${t.dice_roll?`salió <b>${t.dice_roll.result}</b>${Number(t.dice_roll.won_extra_card)===1?` · BONUS +1 carta`:``}`:`aún no lanzado`} · Despliegues de la ronda: <b>${t.plays_this_round}/${t.deployment_limit}</b></div><h2 class="h5">Cartas desplegadas</h2><div class="row g-2">${t.cards.map(c=>`<div class="col-6 col-md-4"><div class="tech-card"><b>${e(c.name)}</b><small class="d-block text-secondary">${e(c.category)} · ${e(c.provider)}</small></div></div>`).join('')||'<p class="text-secondary">Sin cartas.</p>'}</div><h2 class="h5 mt-4">Combos activos</h2><div class="d-flex flex-wrap gap-2">${t.combos.map(c=>`<span class="combo-pill">⚡ ${e(c.name)}</span>`).join('')||'<span class="text-secondary">Sin combos.</span>'}</div>`}load();setInterval(load,3000);
</script></body></html>
